using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using System.Security.Cryptography;
using System.Text;
using System.Xml.Linq;
namespace Shixun {
public sealed partial class ReaderApp {
 void Migrate(string directory){try{string folder=Path.GetFullPath(directory);var config=Data.Json().Deserialize<Dictionary<string,object>>(File.ReadAllText(Path.Combine(folder,"config.json"),Encoding.UTF8));string baseUrl=Convert.ToString(config["baseUrl"]);Transport.ValidateUrl(baseUrl);var uids=ConvertData<List<string>>(config["uids"]);if(uids==null)throw new SafeError("旧订阅配置无效。");string token="",credential=Path.Combine(folder,"access-token.xml");if(File.Exists(credential)){var xml=Feeds.Xml(File.ReadAllText(credential));var secret=xml.Descendants().FirstOrDefault(x=>x.Name.LocalName=="SS");if(secret!=null){string hex=secret.Value;byte[] bytes=Enumerable.Range(0,hex.Length/2).Select(i=>Convert.ToByte(hex.Substring(i*2,2),16)).ToArray();var raw=ProtectedData.Unprotect(bytes,null,DataProtectionScope.CurrentUser);token=Encoding.Unicode.GetString(raw);Array.Clear(raw,0,raw.Length);}}
 List<Dictionary<string,object>> history=new List<Dictionary<string,object>>(),hidden=new List<Dictionary<string,object>>();foreach(var file in new[]{"history.json","dismissed.json"}){string path=Path.Combine(folder,file);if(!File.Exists(path))continue;var list=Data.Json().Deserialize<List<Dictionary<string,object>>>(File.ReadAllText(path,Encoding.UTF8));if(file=="history.json")history=list;else hidden=list;}
 lock(store.Gate){string backup=Path.Combine(store.Folder,"before-migration.dpapi");if(File.Exists(Path.Combine(store.Folder,"state.dpapi")))File.Copy(Path.Combine(store.Folder,"state.dpapi"),backup,true);var sourceIds=new Dictionary<string,string>();foreach(var uidValue in uids){string uid=Convert.ToString(uidValue),url=baseUrl.TrimEnd('/')+"/rss/weibo/user/"+Uri.EscapeDataString(uid);var source=store.State.sources.FirstOrDefault(s=>s.url==url);if(source==null){source=new Source{name=history.Where(h=>S(h,"uid")==uid).Select(h=>S(h,"author")).FirstOrDefault()??"私有订阅",url=url,group="已迁移订阅",privateSource=true,initialized=true,imageReferer="https://weibo.com/",nextRun=Data.Now()+10000};store.State.sources.Add(source);}sourceIds[uid]=source.id;if(token.Length>0)store.State.credentials[source.id]=new RequestProfile{mode="bearer",token=token};}
 foreach(var record in history){string uid=S(record,"uid");if(!sourceIds.ContainsKey(uid))continue;string guid=S(record,"id"),id=Feeds.Hash(sourceIds[uid]+"\n"+guid);if(store.State.articles.Any(a=>a.id==id))continue;DateTimeOffset date;if(!DateTimeOffset.TryParse(S(record,"publishedAt"),out date))continue;var article=new Article{id=id,guid=guid,source=sourceIds[uid],title=S(record,"title"),summary=S(record,"body"),html=S(record,"html"),link=S(record,"link"),author=S(record,"author"),time=(date-new DateTimeOffset(1970,1,1,0,0,0,TimeSpan.Zero)).TotalMilliseconds,firstSeen=Data.Now(),read=true};object imgs;if(record.TryGetValue("images",out imgs)&&imgs is object[])article.images=((object[])imgs).Select(Convert.ToString).Where(x=>x.StartsWith("https://")).ToList();store.State.articles.Add(article);store.State.seen.Add(new Mark{id=id,time=Data.Now()});}
 foreach(var record in hidden)foreach(var sourceId in sourceIds.Values)store.State.deleted.Add(new Mark{id=Feeds.Hash(sourceId+"\n"+S(record,"id")),time=Data.Now()});
 string rulesPath=Path.Combine(folder,"categories.json");if(File.Exists(rulesPath)){var rules=Data.Json().Deserialize<Dictionary<string,string>>(File.ReadAllText(rulesPath,Encoding.UTF8));foreach(var pair in rules)if(!store.State.categories.Any(c=>c.name==pair.Key))store.State.categories.Add(new Category{name=pair.Key,pattern=pair.Value});foreach(var a in store.State.articles)a.category=Rules.Classify(store.State,a);}
 string oldStartup=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.Startup),"WeiboRSS.lnk");if(File.Exists(oldStartup)){store.State.settings.autostart=true;SetStartup(true);}store.Clean();store.Log("legacy migration completed");}Push();}catch(Exception ex){throw ex is SafeError?ex:new SafeError("迁移失败；旧客户端文件未修改，迁移前备份保留在本机。");}}
}
}
